#include "hh/frontend/OverlayModel.h"
#include <algorithm>
namespace hh::frontend {
std::vector<OverlayDescriptor> OverlayModel::requiredDescriptors() { return {
{OverlayId::Cleanliness,"Cleanliness","%",0,1000,"Dirty / text warning","Clean / text OK"}, {OverlayId::GuestSatisfaction,"Guest satisfaction","%",0,1000,"Dissatisfied / down marker","Satisfied / up marker"}, {OverlayId::GuestTraffic,"Guest traffic","guests/min",0,10000,"Low traffic / sparse","High traffic / dense"}, {OverlayId::StaffTraffic,"Staff traffic","staff/min",0,10000,"Low traffic / sparse","High traffic / dense"}, {OverlayId::RoomQuality,"Room quality","score",0,1000,"Low quality / minus","High quality / plus"}, {OverlayId::RoomStatus,"Room status","status",0,7,"Unavailable / status label","Sellable / status label"}, {OverlayId::Noise,"Noise","dBA",0,120000,"Quiet / low-wave","Loud / high-wave"}, {OverlayId::Temperature,"Temperature","C",-20000,50000,"Cold / down-arrow","Hot / up-arrow"}, {OverlayId::ElectricalLoad,"Electrical load","kW",0,1000000,"Low load / low-bar","High load / high-bar"}, {OverlayId::WaterDemand,"Water / plumbing demand","L/min",0,1000000,"Low demand / low-bar","High demand / high-bar"}, {OverlayId::MaintenanceCondition,"Maintenance condition","%",0,1000,"Poor / wrench-warning","Good / wrench-ok"}, {OverlayId::OpenTaskDensity,"Open-task density","tasks/area",0,10000,"Few / count label","Many / count label"}, {OverlayId::StaffUtilization,"Staff utilization","%",0,1000,"Idle / hollow marker","Busy / filled marker"}, {OverlayId::QueueWait,"Queue length / wait","seconds",0,86400,"Short / clock-low","Long / clock-high"}, {OverlayId::ElevatorCongestion,"Elevator congestion","riders/min",0,10000,"Clear / low marker","Congested / high marker"}, {OverlayId::FireSafety,"Fire safety","coverage",0,1000,"Unsafe / warning icon","Covered / shield icon"}, {OverlayId::SecurityCoverage,"Security coverage","coverage",0,1000,"Uncovered / warning icon","Covered / shield icon"}, {OverlayId::Revenue,"Revenue per room / area","cents",0,100000000,"Low / currency-down","High / currency-up"}}; }
std::optional<OverlaySample> OverlayModel::sampleFor(EntityId entityId) const { const auto it = std::find_if(snapshot_.samples.begin(), snapshot_.samples.end(), [entityId](const OverlaySample& sample) { return sample.entityId == entityId; }); if (it == snapshot_.samples.end()) return std::nullopt; return *it; }
bool OverlayModel::hasNonColorSemantics() const noexcept { for (const auto& sample : snapshot_.samples) if (sample.exactText.empty() || sample.semanticText.empty()) return false; return true; }
} // namespace hh::frontend
